import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
    static final long MOD = 998244353;
    static int MAX = 2000005;
    static long[] A = new long[MAX];
    static long[] inv = new long[MAX];
    
    static void precompute(){
        inv[1] = 1;
        for(int i = 2; i < MAX; i++){
            inv[1] = 1;
            inv[i] = (MOD - (MOD / i) * inv[(int) MOD % i] % MOD) % MOD;
        }
        A[0] = 0;
        for(int i = 1; i < MAX; i++){
            A[i] = (A[i - 1] + inv[i]) % MOD;
        }
    }
	public static void main (String[] args) throws java.lang.Exception
	{
		// your code goes here
		Scanner sc = new Scanner(System.in);
		int t = sc.nextInt();
		precompute();
		while(t-- > 0){
		    int n = sc.nextInt();
		    long res = 0;
		    for(int k = 1; k  <= n; k++){
		        long val = sc.nextLong();
		        long coeff = (A[k - 1] + A[n - k]) % MOD;
		        res = (res + (val % MOD) * coeff) % MOD; 
		    }
		    System.out.println(res);
		}

	}
}
